class UsageHistoryResponse(TypedDict, total=False):
    items: List[UsageHistoryResponseItem]


class UsageHistoryResponseItem(TypedDict, total=False):
    tenant_id: str
    metric: str
    period: str
    value: int
    period_end: str
    closed_at: str
    updated_at: str


class _UsageItemRequired(TypedDict):
    metric: str
    value: int


class UsageItem(_UsageItemRequired, total=False):
    #: Absent means unlimited.
    limit: int
    #: Current period, e.g. "2026-10"; absent if the counter never resets.
    period: str
    period_end: str
    #: Value is above the limit (overage policy "allow").
    overage: bool
    overage_policy: Literal["block", "allow"]


class _UserRequired(TypedDict):
    id: str
    email: str
    status: Literal["invited", "active", "disabled"]
    #: "internal" or the user directory plugin instance.
    directory: str
    version: int


class User(_UserRequired, total=False):
    name: str
    email_verified: bool
    #: Platform roles.
    roles: List[str]
    external_id: str
    attributes: Dict[str, str]
    created_at: str
    updated_at: str
    last_login_at: str


class _UserCreateRequired(TypedDict):
    email: str


class UserCreate(_UserCreateRequired, total=False):
    name: str
    roles: List[str]
    attributes: Dict[str, str]
    #: Activates the user immediately.
    password: str
    send_invitation: bool


class UserMembershipsResponse(TypedDict, total=False):
    items: List[Member]


class WebAuthnCeremony(TypedDict, total=False):
    #: {"publicKey": ...} for navigator.credentials.create() or get().
    options: Dict[str, Any]
    ceremony: str


class Webhook(TypedDict, total=False):
    id: str
    tenant_id: str
    url: str
    description: str
    types: List[str]
    enabled: bool
    #: Consecutive failed events; the webhook is disabled at webhooks.max_failures.
    failures: int
    created_at: str
    updated_at: str


class WebhookDelivery(TypedDict, total=False):
    id: str
    webhook_id: str
    tenant_id: str
    event_id: str
    event_type: str
    #: The CloudEvent sent.
    payload: Dict[str, Any]
    attempts: int
    status_code: int
    error: str
    success: bool
    duration_ms: int
    created_at: str


class WebhookInput(TypedDict, total=False):
    url: str
    description: str
    #: Event type globs, e.g. "tenant.*"; empty means all.
    types: List[str]
    enabled: bool


class Operations:
    """One method per operation of the Tenarium API.

    Method names are the snake_case operationIds. ``Client`` extends this
    class and supplies ``_request`` and ``_paginate``.
    """

    def _request(self, method: str, path: str, **kwargs: Any) -> Any:  # pragma: no cover
        raise NotImplementedError

    def _paginate(self, fetch: Callable[[Optional[str]], Any]) -> Iterator[Any]:  # pragma: no cover
        raise NotImplementedError

    def accept_invitation(
        self,
        body: AcceptInvitationRequest,
        *,
        idempotency_key: Optional[str] = None,
        headers: Optional[Mapping[str, str]] = None,
    ) -> Any:
        """Accept an invitation by choosing a password.

        ``POST /v1/auth/invitations/accept``
        """
        return self._request(
            "POST",
            "/v1/auth/invitations/accept",
            body=body,
            content_type="application/json",
            public=True,
            idempotency_key=idempotency_key,
            headers=headers,
        )

    def add_domain(
        self,
        id: str,
        body: AddDomainRequest,
        *,
        idempotency_key: Optional[str] = None,
        headers: Optional[Mapping[str, str]] = None,
    ) -> AddDomainResponse:
        """Add a custom domain.

        Returns the TXT record to publish (`_tenarium-challenge.<hostname>`) before verifying.
        Hostnames are unique across tenants; `tenants.reserved_domains` and their subdomains
        cannot be claimed.

        ``POST /v1/tenants/{id}/domains``
        """
        return self._request(
            "POST",
            "/v1/tenants/{id}/domains",
            path_params={"id": id},
            body=body,
            content_type="application/json",
            auto_idempotency_key=True,
            idempotency_key=idempotency_key,
            headers=headers,
        )

    def add_group_member(
        self,
        id: str,
        group: str,
        member: str,
        *,
        headers: Optional[Mapping[str, str]] = None,
    ) -> Group:
        """Add a member to a group.

        ``PUT /v1/tenants/{id}/groups/{group}/members/{member}``
        """
        return self._request(
            "PUT",
            "/v1/tenants/{id}/groups/{group}/members/{member}",
            path_params={"id": id, "group": group, "member": member},
            headers=headers,
        )

    def add_member(
        self,
        id: str,
        body: MemberCreate,
        *,
        idempotency_key: Optional[str] = None,
        headers: Optional[Mapping[str, str]] = None,
    ) -> Member:
        """Add or invite a member.

        Without `user_id` the member is `invited`. Enforces the `members` limit (429).

        ``POST /v1/tenants/{id}/members``
        """
        return self._request(
            "POST",
            "/v1/tenants/{id}/members",
            path_params={"id": id},
            body=body,
            content_type="application/json",
            auto_idempotency_key=True,
            idempotency_key=idempotency_key,
            headers=headers,
        )

    def begin_passkey_login(
        self,
        body: Optional[BeginPasskeyLoginRequest] = None,
        *,
        idempotency_key: Optional[str] = None,
        headers: Optional[Mapping[str, str]] = None,
    ) -> WebAuthnCeremony:
        """Start a passkey sign-in.

        Without `email` the browser may offer any passkey for this site (discoverable
        credentials). Unknown emails get the same answer as known ones.

        ``POST /v1/auth/passkey/begin``
        """
        return self._request(
            "POST",
            "/v1/auth/passkey/begin",
            body=body,
            content_type="application/json",
            public=True,
            idempotency_key=idempotency_key,
            headers=headers,
        )

    def begin_passkey_registration(
        self,
        *,
        idempotency_key: Optional[str] = None,
        headers: Optional[Mapping[str, str]] = None,
    ) -> WebAuthnCeremony:
        """Start registering a passkey.

        Returns `options` for `navigator.credentials.create()` (decode the base64url fields)
        and an opaque `ceremony` to send back with the result within 5 minutes.

        ``POST /v1/me/passkeys/register/begin``
        """
        return self._request(
            "POST",
            "/v1/me/passkeys/register/begin",
            idempotency_key=idempotency_key,
            headers=headers,
        )

    def begin_totp(
        self,
        *,
        idempotency_key: Optional[str] = None,
        headers: Optional[Mapping[str, str]] = None,
    ) -> BeginTOTPResponse:
        """Start TOTP enrollment.

        Returns a new secret and an `otpauth://` URL (show it as a QR code). Nothing changes
        for login until it is confirmed. 409 if two-factor authentication is already on.

        ``POST /v1/me/mfa/totp``
        """
        return self._request(
            "POST",
            "/v1/me/mfa/totp",
            idempotency_key=idempotency_key,
            headers=headers,
        )

    def cancel_scheduled_action(
        self,
        id: str,
        action: str,
        *,
        headers: Optional[Mapping[str, str]] = None,
    ) -> ScheduledAction:
        """Cancel a pending action.

        ``DELETE /v1/tenants/{id}/schedule/{action}``
        """
        return self._request(
            "DELETE",
            "/v1/tenants/{id}/schedule/{action}",
            path_params={"id": id, "action": action},
            headers=headers,
        )

    def change_my_password(
        self,
        body: ChangeMyPasswordRequest,
        *,
        idempotency_key: Optional[str] = None,
        headers: Optional[Mapping[str, str]] = None,
    ) -> None:
        """Change the caller's password.

        ``POST /v1/me/password``
        """
        return self._request(
            "POST",
            "/v1/me/password",
            body=body,
            content_type="application/json",
            idempotency_key=idempotency_key,
            headers=headers,
        )

    def check_domain(
        self,
        *,
        domain: str,
        headers: Optional[Mapping[str, str]] = None,
    ) -> Any:
        """On-demand TLS permission check.

        Unauthenticated. 200 if a certificate may be issued for the domain (verified, tenant
        live), else 404. Point Caddy's `on_demand_tls { ask ... }` here.

        ``GET /v1/domains/check``
        """
        return self._request(
            "GET",
            "/v1/domains/check",
            query={
                "domain": domain,
            },
            public=True,
            headers=headers,
        )

    def clone_tenant(
        self,
        id: str,
        body: CloneTenantRequest,
        *,
        idempotency_key: Optional[str] = None,
        headers: Optional[Mapping[str, str]] = None,
    ) -> Tenant:
        """Clone a tenant.

        Creates a tenant with the source's plan, add-ons, region, labels, settings, features,
        limits, branding and custom roles, labelled `tenarium.io/cloned-from`. With
        `members: true` its active members are added too. Domains, SSO, API keys, webhooks and
        usage are not copied. Needs `tenants:create` (and `plans:write` when the source has a plan
        or overrides); the caller must hold every action of the copied roles.

        ``POST /v1/tenants/{id}/clone``
        """
        return self._request(
            "POST",
            "/v1/tenants/{id}/clone",
            path_params={"id": id},
            body=body,
            content_type="application/json",
            auto_idempotency_key=True,
            idempotency_key=idempotency_key,
            headers=headers,
        )

    def confirm_email_change(
        self,
        body: ConfirmEmailChangeRequest,
        *,
        idempotency_key: Optional[str] = None,
        headers: Optional[Mapping[str, str]] = None,
    ) -> User:
        """Confirm an email change.

        Completes `POST /v1/me/email` with the token from the confirmation link.

        ``POST /v1/auth/email-change/confirm``
        """
        return self._request(
            "POST",
            "/v1/auth/email-change/confirm",
            body=body,
            content_type="application/json",
            public=True,
            idempotency_key=idempotency_key,
            headers=headers,
        )

    def confirm_password_reset(
        self,
        body: ConfirmPasswordResetRequest,
        *,
        idempotency_key: Optional[str] = None,
        headers: Optional[Mapping[str, str]] = None,
    ) -> None:
        """Set a new password with a reset token.

        ``POST /v1/auth/password-reset/confirm``
        """
        return self._request(
            "POST",
            "/v1/auth/password-reset/confirm",
            body=body,
            content_type="application/json",
            public=True,
            idempotency_key=idempotency_key,
            headers=headers,
        )

    def confirm_totp(
        self,
        body: OTPRequest,
        *,
        idempotency_key: Optional[str] = None,
        headers: Optional[Mapping[str, str]] = None,
    ) -> RecoveryCodes:
        """Confirm TOTP enrollment.

        Enables two-factor login and returns 10 single-use recovery codes, shown only once.

        ``POST /v1/me/mfa/totp/confirm``
        """
        return self._request(
            "POST",
            "/v1/me/mfa/totp/confirm",
            body=body,
            content_type="application/json",
            idempotency_key=idempotency_key,
            headers=headers,
        )

    def create_group(
        self,
        id: str,
        body: GroupInput,
        *,
        idempotency_key: Optional[str] = None,
        headers: Optional[Mapping[str, str]] = None,
    ) -> Group:
        """Create a group.

        Members of a group additionally hold its roles. Granting roles needs the caller to hold their actions.

        ``POST /v1/tenants/{id}/groups``
        """
        return self._request(
            "POST",
            "/v1/tenants/{id}/groups",
            path_params={"id": id},
            body=body,
            content_type="application/json",
            auto_idempotency_key=True,
            idempotency_key=idempotency_key,
            headers=headers,
        )

    def create_o_auth_client(
        self,
        body: OAuthClientInput,
        *,
        idempotency_key: Optional[str] = None,
        headers: Optional[Mapping[str, str]] = None,
    ) -> CreateOAuthClientResponse:
        """Register an application.

        Apps sign users in through Tenarium (`/oauth/authorize`, authorization code + PKCE).
        Confidential clients get a `client_secret`, shown once; `public: true` clients (SPAs,
        mobile apps) get none and must use PKCE. Redirect URIs must be https, loopback http, or
        a private-use scheme. Platform-only (`oauthclients:write`).

        ``POST /v1/oauth-clients``
        """
        return self._request(
            "POST",
            "/v1/oauth-clients",
            body=body,
            content_type="application/json",
            auto_idempotency_key=True,
            idempotency_key=idempotency_key,
            headers=headers,
        )

    def create_plan(
        self,
        body: PlanCreate,
        *,
        idempotency_key: Optional[str] = None,
        headers: Optional[Mapping[str, str]] = None,
    ) -> Plan:
        """Create a plan.

        ``POST /v1/plans``
        """
        return self._request(
            "POST",
            "/v1/plans",
            body=body,
            content_type="application/json",
            auto_idempotency_key=True,
            idempotency_key=idempotency_key,
            headers=headers,
        )

    def create_platform_api_key(
        self,
        body: APIKeyCreate,
        *,
        idempotency_key: Optional[str] = None,
        headers: Optional[Mapping[str, str]] = None,
    ) -> CreatedAPIKey:
        """Create a platform API key.

        ``POST /v1/api-keys``
        """
        return self._request(
            "POST",
            "/v1/api-keys",
            body=body,
            content_type="application/json",
            auto_idempotency_key=True,
            idempotency_key=idempotency_key,
            headers=headers,
        )

    def create_tenant(
        self,
        body: TenantCreate,
        *,
        idempotency_key: Optional[str] = None,
        headers: Optional[Mapping[str, str]] = None,
    ) -> Tenant:
        """Create a tenant.

        Runs `tenant.before_create` hooks, then stores the tenant and emits `tenant.created`.
        With provisioners configured the tenant starts in `provisioning` and becomes
        `active` (or `failed`) asynchronously.

        ``POST /v1/tenants``
        """
        return self._request(
            "POST",
            "/v1/tenants",
            body=body,
            content_type="application/json",
            auto_idempotency_key=True,
            idempotency_key=idempotency_key,
            headers=headers,
        )

    def create_tenant_api_key(
        self,
        id: str,
        body: APIKeyCreate,
        *,
        idempotency_key: Optional[str] = None,
        headers: Optional[Mapping[str, str]] = None,
    ) -> CreatedAPIKey:
        """Create a tenant API key.

        Returns the secret once, in `key`. Roles are member roles; a tenant-scoped caller can only
        grant roles it holds itself. Keys of tenants that are not active stop working.

        ``POST /v1/tenants/{id}/api-keys``
        """
        return self._request(
            "POST",
            "/v1/tenants/{id}/api-keys",
            path_params={"id": id},
            body=body,
            content_type="application/json",
            auto_idempotency_key=True,
            idempotency_key=idempotency_key,
            headers=headers,
        )

    def create_user(
        self,
        body: UserCreate,
        *,
        idempotency_key: Optional[str] = None,
        headers: Optional[Mapping[str, str]] = None,
    ) -> User:
        """Create or invite a user.

        Without a password the user is `invited` and receives a setup email (from the user
        directory if it sends its own, otherwise through the configured mailer).

        ``POST /v1/users``
        """
        return self._request(
            "POST",
            "/v1/users",
            body=body,
            content_type="application/json",
            auto_idempotency_key=True,
            idempotency_key=idempotency_key,
            headers=headers,
        )

    def create_webhook(
        self,
        id: str,
        body: WebhookInput,
        *,
        idempotency_key: Optional[str] = None,
        headers: Optional[Mapping[str, str]] = None,
    ) -> CreateWebhookResponse:
        """Register a webhook.

        The tenant's events (optionally filtered by `types` globs) are POSTed as CloudEvents
        with Standard Webhooks headers (`webhook-id`, `webhook-timestamp`,
        `webhook-signature`). URLs must be https and public; redirects are not followed.
        The secret is returned only here. Requires `webhooks:write`.

        ``POST /v1/tenants/{id}/webhooks``
        """
        return self._request(
            "POST",
            "/v1/tenants/{id}/webhooks",
            path_params={"id": id},
            body=body,
            content_type="application/json",
            auto_idempotency_key=True,
            idempotency_key=idempotency_key,
            headers=headers,
        )

