    def delete_tenant(
        self,
        id: str,
        *,
        force: Optional[bool] = None,
        headers: Optional[Mapping[str, str]] = None,
    ) -> Tenant:
        """Delete a tenant.

        Starts deletion. Tenants with live child tenants cannot be deleted.

        With `tenants.deletion_grace_period` configured, the tenant is instead suspended
        (reason `pending deletion`) and a `delete` action is scheduled for the end of the
        grace period; `POST /v1/tenants/{id}/restore` undoes it until then. Repeating the
        request returns the same scheduled deletion. `force=true` deletes immediately and
        requires the platform-only `tenants:purge` permission.

        ``DELETE /v1/tenants/{id}``
        """
        return self._request(
            "DELETE",
            "/v1/tenants/{id}",
            path_params={"id": id},
            query={
                "force": force,
            },
            headers=headers,
        )

