    def impersonate_user(
        self,
        id: str,
        body: ImpersonateUserRequest,
        *,
        idempotency_key: Optional[str] = None,
        headers: Optional[Mapping[str, str]] = None,
    ) -> TokenPair:
        """Act as a user (support access).

        Returns a short-lived, tenant-scoped access token for the user (no refresh token),
        carrying the caller in the RFC 8693 `act` claim. Every action taken with it is recorded
        with actor `core/token:<user>;impersonated-by=<caller>`, and the session itself as
        `user.impersonated`. With `auth.impersonation.require_consent` (default) the user must
        first create a consent code (`POST /v1/me/impersonation-consent`), which is single
        use; 403 `consent_required` otherwise. Users with platform roles cannot be
        impersonated, and impersonated sessions cannot change credentials, export or erase
        data, create API keys, webhooks or roles, change SSO, or impersonate. Platform-only
        (`users:impersonate`).

        ``POST /v1/users/{id}/impersonate``
        """
        return self._request(
            "POST",
            "/v1/users/{id}/impersonate",
            path_params={"id": id},
            body=body,
            content_type="application/json",
            idempotency_key=idempotency_key,
            headers=headers,
        )

