    def record_usage(
        self,
        id: str,
        metric: str,
        body: RecordUsageRequest,
        *,
        idempotency_key: Optional[str] = None,
        headers: Optional[Mapping[str, str]] = None,
    ) -> UsageItem:
        """Record usage.

        Atomically adds `delta` (negative releases quota) to the metric's current period
        (`usage.metrics.<metric>.period`: day, month, year or never). With the default
        `block` policy, an increment that would exceed
        the tenant's limit is refused with 429 and emits `tenant.quota_exceeded`; with `allow`
        it is recorded and `overage` is true. Crossing a configured threshold emits
        `tenant.usage_threshold_reached`.
        Only active tenants can consume quota.

        ``POST /v1/tenants/{id}/usage/{metric}``
        """
        return self._request(
            "POST",
            "/v1/tenants/{id}/usage/{metric}",
            path_params={"id": id, "metric": metric},
            body=body,
            content_type="application/json",
            auto_idempotency_key=True,
            idempotency_key=idempotency_key,
            headers=headers,
        )

